/* XORA Phase 1 UX PROTOTYPE ONLY.
 * No backend, authentication, payments, identity verification, or real users.
 * All people, accounts, payment records and settlements are fictional.
 * Nothing is persisted or transmitted. Never deploy as a live member/payment service.
 */
'use strict';
const people = [
 {id:'amina',name:'Amina',age:27,area:'Ntinda, Kampala',intent:'both',gender:'Woman',bio:'Coffee walks, live music and sincere conversation. Curious about what a good connection can grow into.',interests:['Coffee','Live music','Travel'],tone:'p1'},
 {id:'daniel',name:'Daniel',age:30,area:'Entebbe',intent:'date',gender:'Man',bio:'A little old-fashioned about kindness; enthusiastic about books, hiking and thoughtful dates.',interests:['Reading','Hiking','Cooking'],tone:'p2'},
 {id:'lillian',name:'Lillian',age:28,area:'Bukoto, Kampala',intent:'casual',gender:'Woman',bio:'Busy schedule, good humor, spontaneous conversations. Respect and clear intentions matter.',interests:['Art','Nightlife','Food'],tone:'p3'},
 {id:'noah',name:'Noah',age:32,area:'Kira',intent:'both',gender:'Man',bio:'Creative, easygoing and curious. I appreciate genuine profiles and honest expectations.',interests:['Design','Movies','Music'],tone:'p4'},
 {id:'ruth',name:'Ruth',age:29,area:'Kololo, Kampala',intent:'date',gender:'Woman',bio:'A weekend market explorer looking for a lasting connection built on humor and trust.',interests:['Gardens','Fitness','Art'],tone:'p5'},
 {id:'michael',name:'Michael',age:31,area:'Jinja',intent:'casual',gender:'Man',bio:'Here for respectful casual dating and interesting people. Always thoughtful about boundaries.',interests:['Cycling','Photography','Music'],tone:'p6'}
];
const products = [
 {id:'connect-week',name:'Connect Week',price:10000,days:7,kind:'connect',desc:'Additional outgoing invitations for 7 days.'},
 {id:'connect-month',name:'Connect Month',price:25000,days:30,kind:'connect',desc:'Additional outgoing invitations for 30 days.'},
 {id:'connect-quarter',name:'Connect Quarter',price:60000,days:90,kind:'connect',desc:'Additional outgoing invitations for 90 days.'},
 {id:'vip-week',name:'VIP Week',price:20000,days:7,kind:'promotion',desc:'Clearly labeled featured rotation for 7 days.'},
 {id:'spotlight-month',name:'Spotlight Month',price:50000,days:30,kind:'promotion',desc:'Featured placement for 30 days.'},
 {id:'vip-month',name:'VIP Month',price:80000,days:30,kind:'promotion',desc:'Expanded featured placement for 30 days.'}
];
const state = {
 view:'home',admin:false,loggedIn:false,profileApproved:true,mode:'both',city:'all',selectedPerson:'amina',
 signup:{email:'',stage:0},onboardStep:0, onb:{name:'',dob:'',city:'Kampala',gender:'',pref:'everyone',intention:'both',bio:'',interests:'',privacy:true,activity:false,photo:''},
 freeUsed:false,passes:[],promotions:[],invites:[{id:'inv-incoming',from:'lillian',to:'me',status:'pending',origin:'incoming'}],
 saved:[],chats:[],activeChat:null,pass:null,promotion:null,
 chosenPlan:'connect-month',paymentStep:0,activeOrder:null,
 orders:[{id:'XORA-DEMO-0007',product:'connect-week',owner:'sample-account',amount:10000,method:'MTN',tx:'DEMO-SETTLEMENT-0007',payer:'07•• ••• 320',status:'submitted',createdAt:Date.now()-2*3600000,review:{},note:''}],
 review: [{id:'profile-001',name:'Fictional member — Ada',kind:'Profile content',status:'pending',reason:''}],
 tickets:[],flags:{},notice:'',notifications:[{label:'You have a new invitation from a fictional demo member.',date:'Today'}]
};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'UGX '+Number(n).toLocaleString('en-US');
const findPerson=id=>people.find(p=>p.id===id)||people[0];
const findProduct=id=>products.find(p=>p.id===id)||products[0];
const niceDate=ms=>new Intl.DateTimeFormat('en-UG',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Kampala'}).format(new Date(ms))+' EAT';
const shortDate=ms=>new Intl.DateTimeFormat('en-UG',{dateStyle:'medium',timeZone:'Africa/Kampala'}).format(new Date(ms));
const customer=()=>state.onb.name||'XORA Member';
const currentPass=()=>state.passes.find(p=>p.start<=Date.now()&&p.end>Date.now())||null;
const nextEntitlementStart=kind=>Math.max(Date.now(),...((kind==='connect'?state.passes:state.promotions).map(e=>e.end)));

const memberNav=[['discover','Discover'],['invitations','Invitations'],['messages','Messages'],['membership','Membership'],['settings','My profile']];
const adminNav=[['admin','Overview'],['admin-finance','Payment reviews'],['admin-profiles','Profile reviews'],['admin-safety','Safety & support'],['admin-members','Members'],['admin-settings','Settings / audit']];
function nav(view,param){state.view=view; if(param) state.selectedPerson=param; location.hash='#'+view; render();window.scrollTo({top:0,behavior:'instant'});}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('show'),3300);}
function demoLogin(){state.loggedIn=true;state.profileApproved=true;state.admin=false;nav('discover');toast('Member demonstration opened. All profiles are fictional.');}
function guestHeader(){return `<a href="#home" data-action="goto" data-to="home" class="brand"><span class="mark">X</span>XORA</a><nav class="nav" aria-label="Main navigation"><a href="#home" data-action="goto" data-to="home">Home</a><a href="#how" data-action="goto" data-to="how">How it works</a><a href="#pricing" data-action="goto" data-to="pricing">Pricing</a><a href="#safety" data-action="goto" data-to="safety">Safety</a></nav><div class="top-actions"><button class="button secondary small" data-action="goto" data-to="signup">Join free</button><button class="button small" data-action="demo-login">Explore demo</button></div>`;}
function memberHeader(){return `<a href="#discover" data-action="goto" data-to="discover" class="brand"><span class="mark">X</span>XORA</a><nav class="nav" aria-label="Member navigation">${memberNav.map(([v,l])=>`<a href="#${v}" data-action="goto" data-to="${v}" class="${state.view===v?'active':''}">${l}</a>`).join('')}<a href="#support" data-action="goto" data-to="support">Help</a></nav><div class="top-actions"><button class="button secondary small" data-action="goto" data-to="state-gallery" aria-label="View UX states">UX states</button><button class="button small" data-action="enter-admin">Admin demo</button></div>`;}
function adminHeader(){return `<a href="#admin" data-action="goto" data-to="admin" class="brand"><span class="mark">X</span>XORA <span class="pill">STAFF DEMO</span></a><nav class="nav" aria-label="Staff demo navigation"><a href="#admin" data-action="goto" data-to="admin">Overview</a><a href="#admin-finance" data-action="goto" data-to="admin-finance">Payments</a><a href="#admin-profiles" data-action="goto" data-to="admin-profiles">Reviews</a></nav><div class="top-actions"><button class="button secondary small" data-action="exit-admin">Return to member</button></div>`;}
function bottomNav(){if(!state.loggedIn||state.admin)return '';return `<nav class="bottom-nav" aria-label="Member mobile navigation">${[['discover','⌕','Discover'],['invitations','♡','Invites'],['messages','✉','Messages'],['membership','◈','Plans'],['settings','◯','Profile']].map(([v,i,l])=>`<button class="${state.view===v?'active':''}" data-action="goto" data-to="${v}"><span aria-hidden="true">${i}</span>${l}</button>`).join('')}</nav>`;}
function render(){
 const adminView=state.admin;
 let output='';
 const view=state.view;
 if(adminView){output=({admin:adminOverview,'admin-finance':adminFinance,'admin-payment-detail':adminPaymentDetail,'admin-profiles':adminProfiles,'admin-safety':adminSafety,'admin-members':adminMembers,'admin-settings':adminSettings}[view]||adminOverview)();}
 else {output=({home:home,how:how,pricing:pricing,safety:safety,signup:signup,onboarding:onboarding,review:reviewStatus,discover:discover,profile:profile,invitations:invitations,messages:messages,membership:membership,promote:promote,checkout:checkout,'payment-status':paymentStatus,settings:settings,support:support,'state-gallery':statesGallery}[view]||home)();}
 document.getElementById('app').innerHTML=`<div class="shell"><div class="demo-banner">PHASE 1 INTERACTIVE PROTOTYPE • FICTIONAL DATA • NO REAL LOGIN, PAYMENTS OR ID CHECKS</div><header class="topbar"><div class="top-inner">${adminView?adminHeader():state.loggedIn?memberHeader():guestHeader()}</div></header><main id="main" tabindex="-1" class="container">${output}</main><footer class="footer">XORA concept prototype · All people and payment records are fictional · Adult dating and consensual casual connections only · No paid-sex arrangements</footer>${bottomNav()}</div>`;
 document.title=`XORA · ${view.replace(/-/g,' ')} · Phase 1 Prototype`;
}
function home(){return `<section class="hero section"><div class="hero-copy"><div class="eyebrow">Premium connections · Adult members only</div><h1>Meet people.<br><span style="color:var(--gold)">On your terms.</span></h1><p>Find people who share your intentions. Build something meaningful or keep it casual—with clear boundaries, private profiles and control over who you connect with.</p><div class="hero-actions"><button class="button" data-action="goto" data-to="signup">Join XORA for free →</button><button class="button outline" data-action="demo-login">Explore member preview</button></div><div class="badges"><span class="pill">18+ only</span><span class="pill">Date / Casual / Both</span><span class="pill">Private discovery</span></div></div></section>
 <section class="section"><div class="section-heading"><div><div class="eyebrow">Your intentions matter</div><h2>One space. Two ways to connect.</h2></div></div><div class="grid cols-2"><div class="card"><div class="eyebrow">01 / XORA Date</div><h3>Give romance room to grow</h3><p class="muted">Explore people interested in meaningful dating and relationships—with compatibility ahead of popularity.</p><button class="button ghost" data-action="goto" data-to="how">How it works →</button></div><div class="card"><div class="eyebrow">02 / XORA Casual</div><h3>Be clear about your chemistry</h3><p class="muted">Respectful, consensual casual dating with shared expectations. You can choose Both or change intentions later.</p><button class="button ghost" data-action="goto" data-to="safety">Our safety approach →</button></div></div></section>
 <section class="section"><div class="section-heading"><h2>Designed for trust, not pressure</h2></div><div class="grid cols-3"><div class="card"><div class="subhead">✦ One free introduction</div><p class="muted">It counts only when the other adult accepts. Incoming requests and existing conversations stay free.</p></div><div class="card"><div class="subhead">◈ Privacy controls</div><p class="muted">Only approved adults can see member profiles. Your phone number and precise location remain private.</p></div><div class="card"><div class="subhead">✓ Honest pricing</div><p class="muted">Choose 7, 30 or 90 days when you need more introductions. No automatic billing.</p></div></div></section>`;}
function how(){return `<div class="section-heading"><div><div class="eyebrow">A calmer way to connect</div><h1 class="page-title">How XORA works</h1><p class="lead">Every step centers privacy and consent. Registration is free and paid plans never guarantee a reply.</p></div></div><div class="grid cols-3">${[['01','Join and set intention','Create a private account, confirm adulthood, and select Date, Casual or Both.'],['02','Create your profile','Add a public display name, approximate area, short bio and permitted photo.'],['03','Get reviewed','Account eligibility and profile content are checked separately before public discovery inside XORA.'],['04','Discover','Find compatible, approved adults. A displayed badge has a specific meaning.'],['05','Send an invitation','Your first outgoing introduction is free if accepted. Incoming invitations are always free.'],['06','Choose a pass if wanted','When the first outgoing introduction is used, select a 7-, 30- or 90-day pass.']].map(([n,h,d])=>`<div class="card"><span class="eyebrow">${n}</span><h3>${h}</h3><p class="muted">${d}</p></div>`).join('')}</div><div class="action-row"><button class="button" data-action="goto" data-to="signup">Start free</button><button class="button secondary" data-action="goto" data-to="pricing">See clear pricing</button></div>`;}
function priceCard(p){return `<div class="card pricing-card ${p.id==='connect-month'?'featured':''}"><div class="eyebrow">${p.kind==='connect'?'Connect pass':'Profile promotion'}</div><h3>${esc(p.name)}</h3><div class="price">${money(p.price)} <small>/ ${p.days} days</small></div><p class="muted">${esc(p.desc)}</p><ul class="list-clean micro"><li>Manual payment review</li><li>Starts at admin approval</li><li>No auto-renewal</li></ul><button class="button ${p.kind==='promotion'?'secondary':''} full" data-action="buy" data-plan="${p.id}">Choose ${esc(p.name)}</button></div>`;}
function pricing(){return `<div class="section"><div class="eyebrow">Transparent, timed access</div><h1 class="page-title">Choose what works for you</h1><p class="lead">Free accounts can browse approved profiles, receive invitations, and keep established conversations. Your first accepted outgoing introduction is free. Paid plans unlock additional outgoing invitations while active.</p></div><div class="notice">No lifetime access. No auto-renewal or in-app wallet. Prices are proposals, subject to legal and payment-provider approval. <strong>Never pay someone for a meeting or for their consent.</strong></div><h2>Connect Passes</h2><div class="grid cols-3 section">${products.filter(p=>p.kind==='connect').map(priceCard).join('')}</div><h2>Optional visibility packages</h2><p class="muted">These packages buy clearly labeled placement, not identity verification, matches or responses.</p><div class="grid cols-3 section">${products.filter(p=>p.kind==='promotion').map(priceCard).join('')}</div>`;}
function safety(){return `<div class="eyebrow">Safety by design</div><h1 class="page-title">Privacy, consent & account safety</h1><p class="lead">XORA is for adults only. Dating intentions are not promises of contact, and users control who can message them.</p><div class="grid cols-2"><div class="card"><h3>Profiles are private</h3><p>Non-members cannot browse sensitive profiles. Display approximate areas, not precise coordinates. Phone numbers and age evidence are not public.</p></div><div class="card"><h3>Verification has limits</h3><p>Age eligibility, email ownership, photo approval and identity review are different checks. No badge means another person is guaranteed safe.</p></div><div class="card"><h3>Consent can change</h3><p>Every invitation can be declined; matched members can block or end a conversation. Paid packages cannot override a person's boundaries.</p></div><div class="card"><h3>Report serious concerns</h3><p>Harassment, coercion, impersonation, scams and suspected underage accounts receive dedicated safety handling. Do not share PINs or OTPs.</p></div></div><div class="notice warn">Prototype only: reporting, verification and safety review are simulated here. Do not share real identity documents, financial records or personal stories with this prototype.</div><div class="action-row"><button class="button" data-action="goto" data-to="support">Help and report</button><button class="button secondary" data-action="goto" data-to="settings">Privacy preferences</button></div>`;}
function signup(){return `<div class="form-card card"><div class="eyebrow">Step 1 of 2 · Create account</div><h1 class="page-title">Welcome to XORA</h1><p class="lead">One account for Date, Casual or Both. No fee to join.</p><form data-form="signup"><label for="email">Email address <span class="muted">(required)</span></label><input id="email" name="email" type="email" placeholder="you@example.com" autocomplete="off" required /><label for="pw">Password <span class="muted">(required)</span></label><input id="pw" name="password" type="password" minlength="8" placeholder="At least 8 characters" autocomplete="new-password" required/><label for="confirm">Confirm password</label><input id="confirm" name="confirm" type="password" minlength="8" required/><label><input type="checkbox" name="adult" required/> I confirm I am 18 or older.</label><label><input type="checkbox" name="terms" required/> I accept the <button type="button" class="linkish" data-action="goto" data-to="safety">Terms, Privacy and Community Rules</button> (prototype summary).</label><label><input type="checkbox" name="marketing"/> Send optional marketing updates (unchecked by default).</label><button class="button full" type="submit">Create demo account</button><p class="hint">This prototype does not create an account, email anyone or retain passwords. Production email verification and secure authentication are Phase 2–3 work.</p></form><div class="divider"></div><button class="button secondary full" data-action="demo-login">Skip to approved member demo</button></div>`;}
function onboarding(){const s=state.onboardStep,steps=['Basics','Intentions','Bio & photo','Privacy','Preview']; const w=state.onb;
 const body=[`<form data-form="onb-0"><label for="pname">Public display name (required)</label><input id="pname" name="name" value="${esc(w.name)}" required maxlength="35" placeholder="What should members call you?"/><label for="pdob">Date of birth (private, required)</label><input id="pdob" name="dob" type="date" value="${esc(w.dob)}" required/><p class="hint">Your date of birth is not shown publicly. Production will require an approved adult eligibility check.</p><label for="pcity">Broad city / approximate area</label><select id="pcity" name="city">${['Kampala','Entebbe','Jinja','Mukono','Other Uganda'].map(a=>`<option ${w.city===a?'selected':''}>${a}</option>`).join('')}</select><button type="submit" class="button full">Continue →</button></form>`,
 `<form data-form="onb-1"><label>What are you looking for? <span class="muted">(required)</span></label>${[['date','Date — relationships'],['casual','Casual — consenting adults'],['both','Both — flexible']].map(([v,l])=>`<label class="radio-card ${w.intention===v?'active':''}"><input type="radio" name="intention" value="${v}" ${w.intention===v?'checked':''}/> ${l}</label>`).join('')}<label for="gender">How do you describe your gender? (optional)</label><select name="gender" id="gender"><option value="">Prefer not to say</option>${['Woman','Man','Non-binary','Self-describe'].map(g=>`<option ${w.gender===g?'selected':''}>${g}</option>`).join('')}</select><label for="pref">Interested in discovering (optional)</label><select name="pref" id="pref"><option value="everyone">All compatible adults</option><option value="women">Women</option><option value="men">Men</option><option value="any">Keep private for now</option></select><button class="button full" type="submit">Continue →</button></form>`,
 `<form data-form="onb-2"><label for="bio">Short public introduction (required)</label><textarea id="bio" name="bio" required maxlength="500" placeholder="Say a little about yourself, interests, and what a respectful connection looks like...">${esc(w.bio)}</textarea><label for="interests">Interests (optional)</label><input name="interests" id="interests" value="${esc(w.interests)}" placeholder="Books, hiking, music"/><label for="photo">Profile photo (required to publish)</label><input type="file" id="photo" name="photo" accept="image/*"/><p class="hint">This demo only displays your selected filename. It does not upload files. Non-explicit, self-owned photos only.</p><button type="submit" class="button full">Continue →</button></form>`,
 `<form data-form="onb-3"><label class="radio-card"><input type="checkbox" name="privacy" ${w.privacy?'checked':''}/> Show my profile only to verified-eligible logged-in members (recommended)</label><label class="radio-card"><input type="checkbox" name="activity" ${w.activity?'checked':''}/> Show a recent-activity label (optional)</label><div class="notice">Approximate location only. Phone, birth date and verification evidence never appear on your public profile.</div><button type="submit" class="button full">Preview profile →</button></form>`,
 `<div class="card inset"><h3>${esc(w.name||'Your display name')}</h3><p class="muted">${esc(w.city)} · ${esc(w.intention)} · Fictional demo preview</p><p>${esc(w.bio||'Your introduction appears here.')}</p><p class="hint">Photo: ${esc(w.photo||'No photo selected')} • Date of birth and private contact details hidden</p></div><div class="notice warn">Submitting sends this simulated profile to a fictional review queue. Approval is separate from email ownership and real adult verification.</div><button class="button full" data-action="submit-profile">Submit for review</button>`][s];
 return `<div class="form-card"><div class="eyebrow">Private member setup</div><h1 class="page-title">Build your XORA profile</h1><div class="steps">${steps.map((v,i)=>`<span class="${i===s?'current':i<s?'done':''}">${i+1}. ${v}</span>`).join('')}</div><div class="card">${body}</div><div class="action-row">${s>0?`<button class="button secondary" data-action="step-back">← Back</button>`:''}<button class="button ghost" data-action="save-onboard">Save draft</button></div></div>`;}
function reviewStatus(){return `<div class="form-card card"><div class="eyebrow">Profile review</div><h1 class="page-title">${state.profileApproved?'Your profile is approved':'Your profile is being reviewed'}</h1><span class="pill ${state.profileApproved?'ok':'warn'}">${state.profileApproved?'Approved':'Awaiting review'}</span><p class="muted">${state.profileApproved?'You can discover other approved adults.':'Your details are saved. You cannot be discovered or send invitations until profile and age-eligibility checks are completed.'}</p><div class="action-row">${state.profileApproved?`<button class="button" data-action="goto" data-to="discover">Discover people</button>`:`<button class="button secondary" data-action="enter-admin">Open admin review demo</button>`}<button class="button outline" data-action="goto" data-to="support">Need help?</button></div></div>`;}
function profileCard(p){return `<article class="profile-card"><div class="portrait ${p.tone}"><span class="initial" aria-hidden="true">${esc(p.name[0])}</span><span class="fictional">FICTIONAL DEMO</span></div><div class="profile-body"><h3>${esc(p.name)}, ${p.age}</h3><div class="row"><span class="pill ok">Profile reviewed</span><span class="pill">${p.intent==='both'?'Both':p.intent==='date'?'Date':'Casual'}</span></div><p class="muted">${esc(p.area)}</p><button class="button full" data-action="open-person" data-person="${p.id}">View profile</button></div></article>`;}
function discover(){if(!state.loggedIn)return needLogin();if(!state.profileApproved)return reviewStatus(); const matches=people.filter(p=>(state.mode==='both'||p.intent===state.mode||p.intent==='both')&&(state.city==='all'||p.area.toLowerCase().includes(state.city)));
 return `<div class="section-heading"><div><div class="eyebrow">Private member discovery</div><h1 class="page-title">Discover your kind of connection</h1><p class="lead">Only fictional, approved example profiles are shown here. Changing your mode never changes your plan or resets your free introduction.</p></div><button class="button secondary" data-action="goto" data-to="settings">Privacy settings</button></div><div class="card inset section"><div class="row between"><div><span class="eyebrow">Discovery intention</span><p class="hint">Choose the experience you're exploring today.</p></div><div class="segmented" role="group" aria-label="Connection intention">${[['date','Date'],['casual','Casual'],['both','Both']].map(([k,v])=>`<button aria-pressed="${state.mode===k}" data-action="mode" data-mode="${k}">${v}</button>`).join('')}</div></div><div class="filter-bar"><div class="field"><label for="cityfilter">Approximate area</label><select id="cityfilter" data-change="city"><option value="all">All areas</option><option value="kampala" ${state.city==='kampala'?'selected':''}>Kampala</option><option value="entebbe" ${state.city==='entebbe'?'selected':''}>Entebbe</option><option value="jinja" ${state.city==='jinja'?'selected':''}>Jinja</option><option value="kira" ${state.city==='kira'?'selected':''}>Kira</option></select></div><button class="button ghost" data-action="reset-filters">Clear filters</button></div></div><div class="section-heading"><h2>Suggested profiles <span class="muted micro">(${matches.length})</span></h2><span class="pill">No exact locations</span></div>${matches.length?`<div class="profile-grid">${matches.map(profileCard).join('')}</div>`:`<div class="card center padded-top"><h2>No compatible profiles in this view</h2><p class="muted">Try a nearby area or expand your intention filter.</p><button class="button" data-action="reset-filters">Reset filters</button></div>`}`;}
function profile(){const p=findPerson(state.selectedPerson); const already=state.invites.find(i=>i.to===p.id&&i.origin==='outgoing');return `<div class="row section"><button class="button secondary small" data-action="goto" data-to="discover">← Back to discovery</button><span class="pill">Members-only profile • fictional</span></div><div class="split"><div class="card"><div class="portrait ${p.tone}" style="height:330px;border-radius:14px"><span class="initial">${esc(p.name[0])}</span><span class="fictional">FICTIONAL DEMO</span></div><div class="eyebrow" style="margin-top:20px">Profile overview</div><h1 class="page-title">${esc(p.name)}, ${p.age}</h1><p class="muted">${esc(p.area)} · Intention: ${p.intent==='both'?'Date and Casual':p.intent==='date'?'Date':'Casual'}</p><span class="pill ok">✓ Photo/profile content reviewed</span><p class="lead">${esc(p.bio)}</p><div class="row">${p.interests.map(i=>`<span class="pill">${esc(i)}</span>`).join('')}</div><p class="hint">A reviewed profile is not a safety guarantee. Exact location, private contact details and identity documents are not shown.</p></div><aside class="card"><div class="eyebrow">Connect respectfully</div><h2>Start with a hello</h2><p class="muted">An invitation is a request, never a guarantee. ${esc(p.name)} can accept, decline or ignore it.</p><div class="notice">${state.freeUsed?currentPass()?`Connect Pass active until ${niceDate(currentPass().end)}`:'Your first accepted outgoing introduction has been used.':'Your first accepted outgoing introduction is free.'}</div><button class="button full" ${already&&already.status==='pending'?'disabled':''} data-action="invite" data-person="${p.id}">${already&&already.status==='pending'?'Invitation pending':'Say Hello'}</button><div class="action-row"><button class="button secondary" data-action="save" data-person="${p.id}">${state.saved.includes(p.id)?'★ Saved':'☆ Save'}</button><button class="button danger" data-action="report" data-person="${p.id}">Report / block</button></div></aside></div>`;}
function invitations(){const incoming=state.invites.filter(i=>i.origin==='incoming');const outgoing=state.invites.filter(i=>i.origin==='outgoing');return `<div class="eyebrow">Invitations & consent</div><h1 class="page-title">Your introductions</h1><p class="lead">Incoming requests and replies are free, including when a pass expires. A free outgoing request counts only upon acceptance.</p><div class="grid cols-2"><div class="card"><h2>Received (${incoming.length})</h2>${incoming.length?incoming.map(i=>`<div class="queue-item"><div><strong>${esc(findPerson(i.from).name)}</strong><p class="hint">${i.status==='pending'?'Would like to connect':'Status: '+i.status}</p></div>${i.status==='pending'?`<div class="row"><button class="button small" data-action="accept" data-id="${i.id}">Accept</button><button class="button secondary small" data-action="decline" data-id="${i.id}">Decline</button></div>`:`<span class="pill">${i.status}</span>`}</div>`).join(''):`<p class="muted">No invitations yet.</p>`}</div><div class="card"><h2>Sent (${outgoing.length})</h2>${outgoing.length?outgoing.map(i=>`<div class="queue-item"><div><strong>${esc(findPerson(i.to).name)}</strong><p class="hint">${i.status==='pending'?'Awaiting response (fictional)':'Status: '+i.status}</p></div>${i.status==='pending'?`<div class="row"><button class="button soft small" data-action="simulate-accept" data-id="${i.id}">Simulate acceptance</button><button class="button secondary small" data-action="withdraw" data-id="${i.id}">Withdraw</button></div>`:`<span class="pill">${i.status}</span>`}</div>`).join(''):`<p class="muted">You haven't sent an introduction yet. Try Discover.</p>`}</div></div><div class="action-row"><button class="button" data-action="goto" data-to="discover">Explore profiles</button><button class="button secondary" data-action="goto" data-to="membership">View free allowance</button></div>`;}
function messages(){if(state.chats.length===0)return `<div class="card center padded-top"><div class="eyebrow">Private conversations</div><h1 class="page-title">When someone accepts, a chat opens.</h1><p class="muted">Existing conversations stay free even if your Connect Pass expires. This demo starts with no real messages.</p><button class="button" data-action="goto" data-to="invitations">View invitations</button></div>`;
 const id=state.activeChat||state.chats[0].person;const p=findPerson(id);const chat=state.chats.find(c=>c.person===id)||state.chats[0];return `<div class="eyebrow">Messages</div><h1 class="page-title">Private conversations</h1><div class="split"><div class="card"><div class="tabs">${state.chats.map(c=>`<button data-action="open-chat" data-person="${c.person}" aria-selected="${c.person===chat.person}">${esc(findPerson(c.person).name)}</button>`).join('')}</div><div class="chat-window"><div class="chat-messages" aria-live="polite">${chat.messages.length?chat.messages.map(m=>`<div class="bubble ${m.mine?'mine':''}">${esc(m.text)}</div>`).join(''):`<p class="muted center">You have a new connection. Start with a respectful greeting.</p>`}</div><form class="chat-compose" data-form="message"><input name="message" aria-label="Message" maxlength="500" placeholder="Write a respectful message..." required/><button class="button" type="submit">Send</button></form></div></div><aside class="card"><h3>Chat with ${esc(p.name)}</h3><p class="muted">Mutually accepted connection. Neither person is obliged to continue.</p><button class="button danger full" data-action="unmatch" data-person="${p.id}">End connection</button><button class="button secondary full" style="margin-top:10px" data-action="report" data-person="${p.id}">Report safety concern</button></aside></div>`;}
function membership(){const pass=currentPass();const active=!!pass;const future=state.passes.filter(x=>x.start>Date.now());return `<div class="eyebrow">Membership & receipts</div><h1 class="page-title">Your XORA access</h1><div class="grid cols-3 section"><div class="card"><div class="eyebrow">Free outgoing introduction</div><div class="stat">${state.freeUsed?'Used':'Available'}</div><p class="muted">${state.freeUsed?'Your first accepted outgoing introduction has been consumed.':'This counts only after your outgoing invitation is accepted.'}</p></div><div class="card"><div class="eyebrow">Connect Pass</div><div class="stat">${active?'Active':'Free plan'}</div><p class="muted">${active?`${esc(findProduct(pass.product).name)} until ${niceDate(pass.end)}`:'Incoming invitations and established chats remain free.'}</p></div><div class="card"><div class="eyebrow">Payments</div><div class="stat">${state.orders.filter(o=>o.owner==='demo-member').length}</div><p class="muted">Order records remain available after access expires.</p></div></div><div class="section-heading"><h2>Connect Passes</h2><button class="button secondary" data-action="goto" data-to="promote">Optional visibility boosts</button></div><div class="grid cols-3 section">${products.filter(p=>p.kind==='connect').map(priceCard).join('')}</div>${future.length?`<div class="notice ok">${future.length} renewal(s) queued after your current pass. Remaining paid days are preserved.</div>`:''}<h2>Orders & receipts</h2><div class="card">${state.orders.filter(o=>o.owner==='demo-member').length?state.orders.filter(o=>o.owner==='demo-member').map(o=>`<div class="queue-item"><div><strong>${esc(o.id)} · ${esc(findProduct(o.product).name)}</strong><p class="hint">${money(o.amount)} · ${esc(o.status.replace('-',' '))}</p></div><button class="button secondary small" data-action="open-order" data-order="${o.id}">View status</button></div>`).join(''):`<p class="muted">No purchases yet. You never need to pay merely to receive an invitation or reply to an existing connection.</p>`}</div>`;}
function promote(){return `<div class="eyebrow">Optional profile visibility</div><h1 class="page-title">Be discoverable, your way</h1><p class="lead">XORA promotions are clearly labeled and rotated fairly among eligible members. They do not guarantee matches, buy verification or override privacy, safety or preferences.</p><div class="grid cols-3">${products.filter(p=>p.kind==='promotion').map(priceCard).join('')}</div><div class="notice warn">A promotion cannot activate for an unapproved, restricted or paused profile. Financial resolutions follow a published policy.</div>`;}
function checkout(){if(!state.loggedIn)return needLogin(); const p=findProduct(state.chosenPlan),o=state.orders.find(x=>x.id===state.activeOrder);
 if(state.paymentStep===0) return `<div class="form-card"><button class="button ghost" data-action="goto" data-to="${p.kind==='connect'?'membership':'promote'}">← Plans</button><div class="eyebrow">Checkout · Step 1 of 3</div><h1 class="page-title">Review your order</h1><div class="card"><h3>${esc(p.name)}</h3><div class="price">${money(p.price)}</div><dl class="detail-list"><dt>Duration</dt><dd>${p.days} consecutive days</dd><dt>Starts</dt><dd>After independent payment verification and admin activation</dd><dt>Renewal</dt><dd>Manual only, no auto-debit</dd><dt>Ends</dt><dd>At the shown expiry time, in EAT</dd><dt>What stays free</dt><dd>Incoming invitations and existing conversations</dd></dl><div class="notice">Payment is for XORA platform features only, not for introductions to any particular person, meetings or consent.</div><label><input id="terms-check" type="checkbox" data-change="orderterms" ${state.flags.orderterms?'checked':''}/> I understand the manual review, price, duration and refund rules.</label><button class="button full" data-action="create-order" ${state.flags.orderterms?'':'disabled'}>Create order</button></div></div>`;
 if(state.paymentStep===1) return `<div class="form-card"><div class="eyebrow">Checkout · Step 2 of 3</div><h1 class="page-title">Your payment instructions</h1><div class="card"><span class="pill warn">No real payment possible in demo</span><h3>${esc(o?.id||'Order pending')}</h3><dl class="detail-list"><dt>Package</dt><dd>${esc(p.name)}</dd><dt>Amount</dt><dd>${money(p.price)}</dd><dt>Receiving account</dt><dd>NOT CONFIGURED — DEMONSTRATION ONLY</dd><dt>Recipient name</dt><dd>DEMO / DO NOT TRANSFER</dd><dt>Payment method</dt><dd>MTN or Airtel (subject to live approval)</dd></dl><div class="notice warn"><strong>Do not send money.</strong> Real XORA must show a verified, authorized business recipient and independent transaction checks. This screen intentionally provides no payment number.</div><div class="action-row"><button class="button" data-action="paid-next">I have payment details (simulate) →</button><button class="button secondary" data-action="goto" data-to="membership">Review later</button></div></div></div>`;
 return `<div class="form-card"><div class="eyebrow">Checkout · Step 3 of 3</div><h1 class="page-title">Submit transfer details</h1><div class="card"><p>Order <strong>${esc(o?.id||'')}</strong> • ${money(p.price)}</p><form data-form="proof"><label for="method">Payment channel</label><select name="method" id="method" required><option value="MTN">MTN MoMo (demo)</option><option value="Airtel">Airtel Money (demo)</option></select><label for="tx">Provider transaction reference (required)</label><input id="tx" name="tx" required minlength="6" placeholder="DEMO-TXN-12345"/><label for="payer">Sending number (last digits only in demo)</label><input id="payer" name="payer" maxlength="20" placeholder="07•• ••• 123"/><label for="paymenttime">Approximate payment time (optional)</label><input id="paymenttime" name="paymenttime" type="datetime-local"/><label for="proof">Receipt image (optional)</label><input id="proof" name="proof" type="file" accept="image/*"/><p class="hint">A screenshot is supporting information only. Admin must confirm actual settled funds independently. Files in this demo are not uploaded.</p><button type="submit" class="button full">Submit for manual review</button></form></div></div>`;}
function paymentStatus(){
 const o=state.orders.find(x=>x.id===state.activeOrder);if(!o)return membership();
 const p=findProduct(o.product);
 const labels={created:'Awaiting payment details',submitted:'Under manual verification','need-details':'More details required','on-hold':'On hold',approved:'Approved & activated',rejected:'Unable to verify','refund-review':'Refund review'};
 const approved=o.status==='approved';
 const timestamps=approved?`<dt>Starts</dt><dd>${niceDate(o.activatedAt)}</dd><dt>Expires</dt><dd>${niceDate(o.endAt)}</dd>`:'';
 const progress=o.status==='created'?'Transfer not submitted':o.status==='need-details'?'Member details need correction':'Member details submitted';
 const details=o.status==='need-details'?`<div class="notice warn">${esc(o.note||'We need an accurate transaction reference.')}</div><button class="button" data-action="correct-order">Update transaction details</button>`:'';
 const pending=o.status==='submitted'?`<div class="notice">Please do not pay again while this order is being checked. In the real service, review hours and a help channel will appear here.</div><button class="button secondary" data-action="enter-admin">Open finance-review demo</button>`:'';
 const created=o.status==='created'?`<button class="button" data-action="resume-order">Continue checkout</button>`:'';
 const succeeded=approved?`<button class="button" data-action="goto" data-to="${p.kind==='connect'?'discover':'promote'}">${p.kind==='connect'?'Return to Discover':'View promotions'}</button>`:'';
 return `<div class="form-card"><div class="eyebrow">Order tracking</div><h1 class="page-title">${esc(labels[o.status]||o.status)}</h1><div class="card">
 <div class="row between"><strong>${esc(o.id)}</strong><span class="pill ${approved?'ok':o.status==='submitted'?'warn':'bad'}">${esc(labels[o.status]||o.status)}</span></div><div class="divider"></div>
 <dl class="detail-list"><dt>Package</dt><dd>${esc(p.name)}</dd><dt>Amount</dt><dd>${money(o.amount)}</dd><dt>Reference</dt><dd>${esc(o.tx||'Not submitted')}</dd><dt>Decision</dt><dd>${approved?'Fictional admin approval':'No entitlement yet'}</dd>${timestamps}</dl>
 <ol class="timeline"><li>Order created<small>${niceDate(o.createdAt)}</small></li><li>${progress}<small>${o.status==='created'?'Awaiting your reference':'Reference received is not proof of settled funds'}</small></li><li>${approved?'Independent verification complete':'Awaiting independent settlement check'}<small>${approved?'One simulated membership entitlement granted':'Review in staff hours; don\'t pay twice'}</small></li></ol>
 ${details}${pending}${created}${succeeded}<button class="button ghost" data-action="goto" data-to="support">Need help with this order?</button></div></div>`;
}
function settings(){return `<div class="eyebrow">Member preferences & safety</div><h1 class="page-title">Your profile & privacy</h1><div class="split"><div class="card"><h3>Profile summary</h3><dl class="detail-list"><dt>Display name</dt><dd>${esc(customer())}</dd><dt>Intention</dt><dd>${state.mode==='both'?'Date and Casual':state.mode==='date'?'Date':'Casual'}</dd><dt>Review</dt><dd>${state.profileApproved?'Approved (demo)':'Pending'}</dd><dt>Contact</dt><dd>Hidden from other members</dd></dl><div class="divider"></div><label for="setting-mode">Discovery intention</label><select id="setting-mode" data-change="setting-mode"><option value="both" ${state.mode==='both'?'selected':''}>Both</option><option value="date" ${state.mode==='date'?'selected':''}>Date</option><option value="casual" ${state.mode==='casual'?'selected':''}>Casual</option></select><p class="hint">Changing intention never changes paid access.</p><label class="radio-card"><input type="checkbox" data-change="paused" ${state.flags.paused?'checked':''}/> Pause my profile's visibility</label><label class="radio-card"><input type="checkbox" data-change="activity" ${state.flags.activity?'checked':''}/> Show a recently active label</label><button class="button secondary" data-action="save-settings">Save preferences</button></div><aside class="card"><h3>Security & account</h3><p class="muted">Real account recovery, devices, data export and erasure require backend support in later phases. Phase 1 defines their experiences and copy.</p><button class="button secondary full" data-action="show-help" data-topic="Export personal data">Request data export</button><button class="button danger full" style="margin-top:10px" data-action="show-help" data-topic="Delete account">Request deletion</button><button class="button ghost full" data-action="goto" data-to="safety">Safety guidance</button></aside></div>`;}
function support(){return `<div class="eyebrow">Help & safety</div><h1 class="page-title">Get assistance without exposing your privacy</h1><p class="lead">Never share a payment PIN, OTP, real ID document or private chat screenshot in this demonstration.</p><div class="grid cols-2"><div class="card"><h3>Ask for help</h3><form data-form="ticket"><label for="topic">Topic</label><select id="topic" name="topic"><option>Payment review</option><option>Profile verification</option><option>Connection issue</option><option>Privacy or deletion</option><option>Safety report</option><option>General question</option></select><label for="details">Describe the issue (fictional demo)</label><textarea id="details" name="details" required placeholder="Please use made-up examples only..."></textarea><button class="button full" type="submit">Submit demo ticket</button></form></div><div class="card"><h3>Safe choices</h3><ul class="list-clean"><li>Block or report accounts that make you uncomfortable.</li><li>Don't share security codes or send money to individual members.</li><li>No verified badge promises a person is safe.</li><li>Report suspected underage accounts promptly.</li></ul><h3>Your demo tickets</h3>${state.tickets.map(t=>`<p class="notice">${esc(t.id)} — ${esc(t.topic)} <span class="pill warn">Open</span></p>`).join('')||`<p class="muted">No tickets submitted yet.</p>`}</div></div>`;}
function statesGallery(){return `<div class="eyebrow">Design system · State inventory</div><h1 class="page-title">Every important state needs a clear next step</h1><p class="lead">UX examples only. These cards document intended system language and treatment; they do not claim functional backend behavior.</p><div class="state-gallery">${[
 ['◯','Loading','Finding compatible people…','Show a calm skeleton, avoid repeated spinners and never expose a prior member’s data.'],
 ['∅','Empty','No matches for these filters.','Offer Reset filters and privacy-friendly alternatives, never invent profiles.'],
 ['⌁','Offline','Your connection appears offline.','Keep entered checkout details locally while possible and offer Retry; never resubmit a new order automatically.'],
 ['!','Form error','Check the highlighted information.','Retain input, identify the exact field, announce error near the field.'],
 ['⌛','Payment pending','Your transfer details were received—not yet verified.','Display order reference, status, staff hours and a correction option; do not grant access.'],
 ['✎','Correction needed','We could not match the transfer reference.','Permit editing the same order. Do not require a second payment.'],
 ['⊘','Restricted','Your profile is not currently discoverable.','Explain permitted next steps and appeals without exposing sensitive enforcement details.'],
 ['✓','Success','Your Connect Pass is active.','Show exact start and expiry time in EAT, receipt and next action.'],
 ['⚐','Safety incident','Your report has been received.','Give a case number, immediate block option and appropriate escalation path.'],
 ['🔒','Permission denied','This area requires an authorized account.','Offer safe navigation rather than exposing data or a staff shortcut.']
 ].map(([i,h,k,d])=>`<div class="state"><div class="icon" aria-hidden="true">${i}</div><h3>${h}</h3><strong>${k}</strong><p class="muted">${d}</p></div>`).join('')}</div><div class="action-row"><button class="button" data-action="goto" data-to="discover">Back to member demo</button></div>`;}
function needLogin(){return `<div class="card center padded-top"><h1 class="page-title">Join XORA to explore</h1><p class="muted">Private member profiles are not visible to visitors.</p><button class="button" data-action="goto" data-to="signup">Join free</button><button class="button secondary" data-action="demo-login">Try fictional member demo</button></div>`;}
function adminLayout(title,subtitle,inner){return `<div class="sidebar-layout"><aside class="side-nav" aria-label="Admin demo navigation">${adminNav.map(([v,l])=>`<button data-action="goto" data-to="${v}" class="${state.view===v?'active':''}">${l}</button>`).join('')}</aside><section><div class="eyebrow">Staff-only design · simulated permissions</div><h1 class="page-title">${title}</h1><p class="lead">${subtitle}</p>${inner}</section></div>`;}
function adminOverview(){const pending=state.orders.filter(o=>o.status==='submitted').length;return adminLayout('Operations overview','A real dashboard prioritizes critical safety and unmatched money ahead of revenue. Counts below are fictional fixtures.',`<div class="grid cols-3 section">${[['Critical safety','1','Review immediately'],['Payments to verify',pending,'Oldest first'],['Profiles to review',state.review.filter(r=>r.status==='pending').length+(state.profileApproved?0:1),'Age check separate'],['Refunds / unmatched','0','Needs reconciliation'],['Support waiting',state.tickets.length,'Assign an owner'],['Active campaigns',state.promotions.filter(x=>x.start<=Date.now()&&x.end>Date.now()).length,'No guaranteed matches']].map(([h,n,d])=>`<div class="metric"><h3>${h}</h3><strong>${n}</strong><p class="hint">${d}</p></div>`).join('')}</div><div class="grid cols-2"><div class="card"><h3>Today's required work</h3><ul class="list-clean"><li>Review critical safety reports before routine finance.</li><li>Compare transfer submissions with official settled funds.</li><li>Handle pending profile review separately from age checks.</li><li>Record reasons for every staff decision.</li></ul><button class="button" data-action="goto" data-to="admin-finance">Open finance queue</button></div><div class="card"><h3>Demonstration limitation</h3><p class="muted">Role switching in this prototype is deliberately not authentication. Real admin access requires named staff logins, MFA, role-based permissions and audit records in later phases.</p><button class="button secondary" data-action="goto" data-to="admin-safety">Open safety queue</button></div></div>`);}
function adminFinance(){return adminLayout('Manual payment queue','Never equate a receipt image with money. Admins independently verify a settled transfer before granting exactly one entitlement.',`<div class="notice warn">No payment integration or actual recipient exists here. All settlements are synthetic test fixtures, not bank/MoMo evidence.</div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Order</th><th>Product</th><th>Expected</th><th>State</th><th>Member</th><th>Next action</th></tr></thead><tbody>${state.orders.map(o=>`<tr><td>${esc(o.id)}</td><td>${esc(findProduct(o.product).name)}</td><td>${money(o.amount)}</td><td><span class="pill ${o.status==='approved'?'ok':'warn'}">${esc(o.status)}</span></td><td>${o.owner==='demo-member'?'Demo member':'Fictional sample'}</td><td><button class="button secondary small" data-action="inspect-order" data-order="${o.id}">Review</button></td></tr>`).join('')}</tbody></table></div></div><div class="action-row"><button class="button secondary" data-action="goto" data-to="admin-settings">View audit demo</button></div>`);}
function adminPaymentDetail(){const o=state.orders.find(o=>o.id===state.activeOrder)||state.orders[0];const p=findProduct(o.product);const done=o.review||{};const checks=[['recipient','Business recipient matches official record'],['settled','Funds settled in independent statement'],['amount','Received amount matches this order'],['unique','Transaction not linked to another order'],['eligible','Member eligible and order not already approved']];const good=checks.every(([k])=>done[k]);return adminLayout('Payment review — '+esc(o.id),'Review member-submitted details against a separately obtained receiving-account record.',`<div class="grid cols-2"><div class="card"><div class="eyebrow">Immutable order</div><dl class="detail-list"><dt>Product</dt><dd>${esc(p.name)}</dd><dt>Expected</dt><dd>${money(o.amount)}</dd><dt>Status</dt><dd>${esc(o.status)}</dd><dt>Reference</dt><dd>${esc(o.tx||'Not entered')}</dd><dt>Channel</dt><dd>${esc(o.method||'Not entered')}</dd><dt>Sender</dt><dd>${esc(o.payer||'Not provided')}</dd></dl><div class="notice">User-uploaded proof alone is <strong>never</strong> independent verification.</div></div><div class="card"><div class="eyebrow">Official settlement workspace</div><h3>Independent verification checklist</h3><p class="hint">This fixture has no real statement. In production, reviewers must inspect authorized receiving-account records outside user-uploaded evidence.</p><div class="checklist">${checks.map(([k,l])=>`<label><input type="checkbox" data-check="${k}" data-order="${o.id}" ${done[k]?'checked':''} ${o.status==='approved'?'disabled':''}/> ${l}</label>`).join('')}</div>${o.status==='approved'?`<div class="notice ok">Order already approved; duplicate activation blocked. ${niceDate(o.activatedAt)}</div>`:`<button class="button full" data-action="approve-order" data-order="${o.id}" ${o.status!=='submitted'||!good?'disabled':''}>Confirm and activate once</button>`}<div class="action-row"><button class="button secondary small" data-action="need-details" data-order="${o.id}" ${o.status==='approved'?'disabled':''}>Request correction</button><button class="button ghost small" data-action="goto" data-to="admin-finance">Back to queue</button></div></div></div>`);}
function adminProfiles(){return adminLayout('Profile and eligibility review','Profile content checks and adult age/identity assurance are separate. Demonstration buttons do not perform real verification.',`<div class="notice warn">Real ID documents and adulthood verification evidence must never be held in this prototype.</div><div class="queue-list">${!state.profileApproved?`<div class="queue-item"><div><strong>${esc(customer())} · Member profile</strong><p class="hint">Awaiting profile review · Age eligibility still a separate production gate</p></div><div class="row"><button class="button small" data-action="approve-demo-profile">Approve fictional profile</button><button class="button secondary small" data-action="request-profile-fix">Request changes</button></div></div>`:''}${state.review.map(r=>`<div class="queue-item"><div><strong>${esc(r.name)}</strong><p class="hint">${esc(r.kind)} · ${esc(r.status)}</p></div>${r.status==='pending'?`<div class="row"><button class="button small" data-action="approve-sample" data-id="${r.id}">Approve content</button><button class="button secondary small" data-action="fix-sample" data-id="${r.id}">Request correction</button></div>`:'<span class="pill">'+esc(r.status)+'</span>'}</div>`).join('')}</div>`);}
function adminSafety(){return adminLayout('Safety reports & support','Safety work has priority over revenue. Staff should view only evidence necessary for the assigned case.',`<div class="queue-item"><div><span class="pill bad">Urgent · fictional fixture</span><h3>Report SFTY-DEMO-14</h3><p class="muted">A demo user reported suspected impersonation. Restrict/triage according to published rules, preserving an auditable reason.</p></div><button class="button danger" data-action="resolve-safety">Triage demo case</button></div><h2>Support requests</h2><div class="card">${state.tickets.length?state.tickets.map(t=>`<div class="queue-item"><div><strong>${esc(t.id)}</strong><p class="hint">${esc(t.topic)} · fictional request</p></div><span class="pill warn">Open</span></div>`).join(''):'<p class="muted">No support tickets in this demo.</p>'}</div>`);}
function adminMembers(){return adminLayout('Member management','Authorized reviewers see only minimum necessary account fields, not raw personal chat contents.',`<div class="card"><dl class="detail-list"><dt>Account</dt><dd>DEMO-MEMBER</dd><dt>Display name</dt><dd>${esc(customer())}</dd><dt>Profile state</dt><dd>${state.profileApproved?'Approved (simulation)':'Pending review'}</dd><dt>Free outgoing</dt><dd>${state.freeUsed?'Consumed':'Not consumed'}</dd><dt>Connect Pass</dt><dd>${currentPass()?esc(findProduct(currentPass().product).name):'None active'}</dd></dl><div class="notice">Admin restriction actions require specific permission, reason code and auditable review in production. There is no privileged override of consent.</div></div>`);}
function adminSettings(){return adminLayout('Configuration & audit','Changing recipients, plan prices or staff permissions requires elevated authorization and recorded approvals.',`<div class="grid cols-2"><div class="card"><h3>Authorized payment channels</h3><p class="muted">No recipient has been configured for this demo.</p><button class="button secondary" disabled>Change payee (requires live approval)</button></div><div class="card"><h3>Staff access</h3><p class="muted">Founder, finance, profile reviewer, verification specialist and safety lead have different privileges in the real product.</p><button class="button secondary" disabled>Manage real staff MFA</button></div></div><h2>Sample event history</h2><div class="card">${state.orders.filter(o=>o.status==='approved').map(o=>`<p class="notice ok">Simulated admin approved ${esc(o.id)} at ${niceDate(o.activatedAt)}. One entitlement generated.</p>`).join('')||'<p class="muted">No demo payment approvals recorded yet.</p>'}</div>`);}
function openOrder(p){state.chosenPlan=p;const product=findProduct(p);if(!state.loggedIn){nav('signup');toast('Join or open the member demo before selecting a package.');return;}if(!state.profileApproved){nav('review');toast('Profile eligibility is required before a paid plan can activate.');return;}state.paymentStep=0;state.flags.orderterms=false;nav('checkout');}
function sendInvite(id){if(!state.loggedIn)return nav('signup');if(!state.profileApproved){nav('review');return;}if(state.flags.paused){toast('Unpause your profile before sending invitations.');return;}if(state.invites.some(i=>i.to===id&&i.origin==='outgoing'&&i.status==='pending')){toast('One invitation is already pending for this person.');return;}if(state.freeUsed&&!currentPass()){nav('membership');toast('Choose a Connect Pass to initiate more introductions.');return;}if(!state.freeUsed&&state.invites.some(i=>i.origin==='outgoing'&&i.status==='pending')){toast('You may have only one active free outgoing request. Withdraw or wait for its outcome.');return;}state.invites.push({id:'inv-'+Date.now(),from:'me',to:id,status:'pending',origin:'outgoing'});nav('invitations');toast('Invitation sent. It is free unless the recipient accepts.');}
function acceptInvite(id,simulate){const invite=state.invites.find(i=>i.id===id);if(!invite||invite.status!=='pending')return;invite.status='accepted';const peer=invite.origin==='incoming'?invite.from:invite.to;if(!state.chats.some(c=>c.person===peer)){state.chats.push({person:peer,messages:[]});}state.activeChat=peer;if(invite.origin==='outgoing'&&!state.freeUsed)state.freeUsed=true;nav('messages');toast(simulate?'Fictional acceptance simulated. First outgoing allowance consumed.':'Incoming invitation accepted. Your free outgoing allowance is unchanged.');}
function approveOrder(id){const o=state.orders.find(o=>o.id===id);if(!o||o.status!=='submitted'){toast('Order not eligible for approval.');return;}const checks=['recipient','settled','amount','unique','eligible'];if(!checks.every(k=>o.review[k])){toast('Complete independent settlement checks first.');return;}o.status='approved';o.activatedAt=Date.now();const p=findProduct(o.product);
const start=o.owner==='demo-member'?nextEntitlementStart(p.kind):o.activatedAt;
o.startAt=start;o.endAt=start+p.days*24*60*60*1000;
if(o.owner==='demo-member'){
 const record={product:p.id,start:o.startAt,end:o.endAt,orderId:o.id};
 (p.kind==='connect'?state.passes:state.promotions).push(record);
}
nav('admin-payment-detail');toast('Demo approval recorded once. No real funds transferred.');}
function handleForm(form){const type=form.dataset.form;const d=new FormData(form);if(type==='signup'){if(d.get('password')!==d.get('confirm')){toast('Passwords do not match.');return;}if(!d.get('adult')||!d.get('terms')){toast('Confirm adulthood and essential terms first.');return;}state.signup.email=d.get('email');state.loggedIn=true;state.profileApproved=false;state.admin=false;state.onboardStep=0;nav('onboarding');toast('Demo account created; real email verification is not available in Phase 1.');return;}
if(type.startsWith('onb-')){const s=Number(type.split('-')[1]);if(s===0){const age=(Date.now()-new Date(d.get('dob')).getTime())/(365.2425*864e5);if(!Number.isFinite(age)||age<18){toast('XORA is available only to adults aged 18 or older.');return;}state.onb.name=d.get('name').trim();state.onb.dob=d.get('dob');state.onb.city=d.get('city');}if(s===1){state.onb.intention=d.get('intention');state.onb.gender=d.get('gender');state.onb.pref=d.get('pref');state.mode=d.get('intention');}if(s===2){state.onb.bio=d.get('bio').trim();state.onb.interests=d.get('interests');state.onb.photo=(d.get('photo')||{}).name||state.onb.photo||'Not uploaded';}if(s===3){state.onb.privacy=!!d.get('privacy');state.onb.activity=!!d.get('activity');}state.onboardStep=Math.min(4,s+1);render();return;}
if(type==='proof'){const o=state.orders.find(o=>o.id===state.activeOrder);if(!o||o.status==='approved'){toast('No pending order to update.');return;}const tx=String(d.get('tx')||'').trim();if(state.orders.some(x=>x.id!==o.id&&x.tx&&x.tx.toLowerCase()===tx.toLowerCase())){toast('This reference was already used. Check your order details.');return;}o.method=d.get('method');o.tx=tx;o.payer=d.get('payer')||'Not provided';o.status='submitted';o.review={};o.note='';state.paymentStep=2;nav('payment-status');toast('Details submitted for simulated review—not proof of payment.');return;}
if(type==='message'){const chat=state.chats.find(c=>c.person===(state.activeChat||state.chats[0]?.person));if(chat){chat.messages.push({mine:true,text:d.get('message').trim()});render();toast('Fictional message added locally.');}return;}
if(type==='ticket'){const t={id:'TICKET-DEMO-'+String(state.tickets.length+1).padStart(3,'0'),topic:d.get('topic'),details:d.get('details')};state.tickets.push(t);render();toast('Fictional support ticket created.');return;}
}
document.addEventListener('submit',e=>{const f=e.target.closest('form[data-form]');if(f){e.preventDefault();handleForm(f);}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.change==='city'){state.city=el.value;render();}if(el.dataset.change==='setting-mode'){state.mode=el.value;render();}if(el.dataset.change==='paused'||el.dataset.change==='activity'){state.flags[el.dataset.change]=el.checked;render();}if(el.dataset.change==='orderterms'){state.flags.orderterms=el.checked;render();}if(el.dataset.check){const o=state.orders.find(o=>o.id===el.dataset.order);if(o&&o.status==='submitted'){o.review[el.dataset.check]=el.checked;render();}}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.matches('a'))e.preventDefault();const a=b.dataset.action;const id=b.dataset.person;switch(a){
case 'goto':nav(b.dataset.to);break;
case 'demo-login':demoLogin();break;
case 'enter-admin':state.admin=true;nav('admin');toast('Staff role switch is simulated, not access control.');break;
case 'exit-admin':state.admin=false;nav('discover');break;
case 'mode':state.mode=b.dataset.mode;render();break;
case 'reset-filters':state.mode='both';state.city='all';render();break;
case 'open-person':nav('profile',id);break;
case 'invite':sendInvite(id);break;
case 'save':state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];render();toast(state.saved.includes(id)?'Saved to your fictional shortlist.':'Removed from saved profiles.');break;
case 'report':state.flags.lastReported=id;nav('support');toast('Use the safety report topic; in the live product a report can be filed from this profile.');break;
case 'buy':openOrder(b.dataset.plan);break;
case 'accept':acceptInvite(b.dataset.id,false);break;
case 'simulate-accept':acceptInvite(b.dataset.id,true);break;
case 'decline':{const inv=state.invites.find(i=>i.id===b.dataset.id);if(inv)inv.status='declined';render();toast('Invitation declined without using an allowance.');break;}
case 'withdraw':{const inv=state.invites.find(i=>i.id===b.dataset.id);if(inv)inv.status='withdrawn';render();toast('Pending invitation withdrawn; free allowance not used.');break;}
case 'open-chat':state.activeChat=id;render();break;
case 'unmatch':state.chats=state.chats.filter(c=>c.person!==id);state.activeChat=state.chats[0]?.person||null;render();toast('Connection ended.');break;
case 'save-onboard':toast('Draft retained during this demonstration session.');break;
case 'step-back':state.onboardStep=Math.max(0,state.onboardStep-1);render();break;
case 'submit-profile':state.profileApproved=false;state.admin=false;nav('review');break;
case 'create-order':if(!state.flags.orderterms)return toast('Accept the pricing and review terms first.');{const p=findProduct(state.chosenPlan);const code='XORA-DEMO-'+String(state.orders.length+1001).padStart(4,'0');state.orders.push({id:code,product:p.id,owner:'demo-member',amount:p.price,status:'created',createdAt:Date.now(),review:{},tx:'',method:'',payer:''});state.activeOrder=code;state.paymentStep=1;state.flags.orderterms=false;render();}break;
case 'paid-next':state.paymentStep=2;render();break;
case 'resume-order':state.paymentStep=1;nav('checkout');break;
case 'correct-order':state.paymentStep=2;nav('checkout');break;
case 'open-order':state.activeOrder=b.dataset.order;nav('payment-status');break;
case 'inspect-order':state.activeOrder=b.dataset.order;nav('admin-payment-detail');break;
case 'approve-order':approveOrder(b.dataset.order);break;
case 'need-details':{const o=state.orders.find(o=>o.id===b.dataset.order);if(o&&o.status!=='approved'){o.status='need-details';o.note='The submitted reference could not be matched to an independently verified transaction. Please recheck the reference and time.';o.review={};render();toast('Correction requested; member should not repay.');}}break;
case 'approve-demo-profile':state.profileApproved=true;render();toast('Fictional profile content approved; real age checks not performed.');break;
case 'request-profile-fix':toast('Demo correction requested. A live version must specify the exact field and reason.');break;
case 'approve-sample':{const r=state.review.find(r=>r.id===b.dataset.id);if(r)r.status='approved';render();}break;
case 'fix-sample':{const r=state.review.find(r=>r.id===b.dataset.id);if(r)r.status='needs changes';render();}break;
case 'resolve-safety':toast('Demo triage recorded; real incident actions require audit and safety-team procedures.');break;
case 'save-settings':toast('Privacy settings updated locally for prototype only.');break;
case 'show-help':nav('support');toast('Choose a privacy topic and submit a fictional ticket: '+b.dataset.topic);break;
default:break;
}});
window.addEventListener('hashchange',()=>{let v=location.hash.slice(1);if(!v||state.view===v)return; state.view=v;if(v.startsWith('admin'))state.admin=true;render();});
const firstHash=location.hash.slice(1);if(firstHash&&/^[a-z-]+$/.test(firstHash)) {state.view=firstHash; state.admin=firstHash.startsWith('admin');}
render();
